target_ir:
- [VBlock]
  - [TextInput] "First Name" -> {{ [abc] user().firstName }}
  - [TextInput] "Last Name" -> {{ [abc] user().lastName }}
  - [Button] "Save Profile" -> trigger(user().update())

- [RepeatingContainer] source={{ [#] store().products }} item_alias="product"
  - [VBlock]
    - [Image] -> {{ [abc] product.imageUrl }}
    - [Text] "{{ [abc] product.title }}"
    - [PriceDisplay] -> {{ [$] product.price }}

- [VBlock]
  - [RepeatingContainer] source={{ [#] cart().items }} item_alias="item"
    - [HBlock]
      - [Text] "{{ [abc] item.name }}"
      - [NumberInput] "Qty" -> {{ [#] item.quantity }}
      - [PriceDisplay] -> {{ [$] item.lineTotal }}
  - [HBlock]
    - [Text] "Subtotal:"
    - [PriceDisplay] -> {{ [$] cart().subtotal }}

- [VBlock]
  - [TextInput] "Street Address" -> {{ [abc] checkout().street }}
  - [TextInput] "City" -> {{ [abc] checkout().city }}
  - [HBlock]
    - [TextInput] "ZIP Code" -> {{ [abc] checkout().zip }}
    - [TextInput] "Country" -> {{ [abc] checkout().country }}

- [VBlock]
  - [Text] "Leave a Review"
  - [NumberInput] "Stars (1-5)" -> {{ [#] reviewDraft().stars }}
  - [TextInput] "Your Feedback" -> {{ [abc] reviewDraft().body }}
  - [Button] "Submit" -> trigger(product().submitReview())

- [VBlock]
  - [TextInput] "Task Name" -> {{ [abc] task().name }}
  - [TextInput] "Description" -> {{ [abc] task().description }}
  - [HBlock]
    - [Text] "Completed"
    - [Toggle] -> {{ [⭘] task().isComplete }}

- [VBlock]
  - [TextInput] "Client Email" -> {{ [abc] invoiceDraft().clientEmail }}
  - [RepeatingContainer] source={{ [#] invoiceDraft().services }} item_alias="svc"
    - [HBlock]
      - [TextInput] "Service Name" -> {{ [abc] svc.name }}
      - [PriceInput] "Cost" -> {{ [$] svc.cost }}
  - [Button] "Generate Invoice" -> trigger(invoiceDraft().create())

- [VBlock]
  - [TextInput] "Event Title" -> {{ [abc] eventDraft().title }}
  - [TextInput] "Start Time" -> {{ [abc] eventDraft().startTime }}
  - [HBlock]
    - [Text] "All Day Event"
    - [Toggle] -> {{ [⭘] eventDraft().isAllDay }}

- [HBlock]
  - [TextInput] "Colleague Email" -> {{ [abc] workspace().inviteEmail }}
  - [VBlock]
    - [Text] "Admin Rights"
    - [Toggle] -> {{ [⭘] workspace().inviteAsAdmin }}
  - [Button] "Send Invite" -> trigger(workspace().sendInvite())

- [HBlock]
  - [TextInput] "Document Title" -> {{ [abc] document().title }}
  - [Text] "Words: {{ [#] document().wordCount }}"

- [RepeatingContainer] source={{ [#] tracker().logs }} item_alias="log"
  - [HBlock]
    - [Text] "{{ [abc] log.projectName }}"
    - [NumberInput] "Hours" -> {{ [#] log.hours }}
    - [Toggle] "Tracking Active" -> {{ [⭘] log.isActive }}

- [HBlock]
  - [Text] "Step {{ [#] form().currentStep }} of {{ [#] form().totalSteps }}"
  - [ProgressBar] progress={{ [#] form().completionPercentage }}
